'use client';

import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { useMenuDetail } from './useMenuDetail';
import ImageGallery from './ImageGallery/ImageGallery';
import BasicInfo from './BasicInfo/BasicInfo';
import MenuActions from './MenuActions/MenuActions';
import Button from '@/components/common/Button';
import styles from './MenuDetailClient.module.css';

interface MenuDetailClientProps {
    menuId: string;
}

export default function MenuDetailClient({ menuId }: MenuDetailClientProps) {
    const router = useRouter();
    const { menu, loading, error } = useMenuDetail(menuId);

    // 로딩 상태
    if (loading) {
        return (
            <main className={styles.container}>
                <div className={styles.loadingWrapper}>
                    <div className={styles.spinner}></div>
                    <p>메뉴 정보를 불러오는 중...</p>
                </div>
            </main>
        );
    }

    // 에러 상태
    if (error) {
        return (
            <main className={styles.container}>
                <div className={styles.errorWrapper}>
                    <p className={styles.errorMessage}>{error}</p>
                    <Link href="/admin/menus">
                        <Button variant="outline">목록으로 돌아가기</Button>
                    </Link>
                </div>
            </main>
        );
    }

    // 메뉴를 찾을 수 없는 경우
    if (!menu) {
        return (
            <main className={styles.container}>
                <div className={styles.errorWrapper}>
                    <p className={styles.errorMessage}>메뉴를 찾을 수 없습니다.</p>
                    <Link href="/admin/menus">
                        <Button variant="outline">목록으로 돌아가기</Button>
                    </Link>
                </div>
            </main>
        );
    }

    const handleDelete = async () => {
        try {
            const response = await fetch(`http://localhost:8080/admin/menus/${menu.id}`, {
                method: 'DELETE',
            });

            if (response.ok) {
                alert('메뉴가 삭제되었습니다.');
                router.push('/admin/menus');
            } else {
                alert('삭제에 실패했습니다.');
            }
        } catch (err) {
            alert('삭제 중 오류가 발생했습니다.');
        }
    };

    return (
        <main className={styles.container}>
            <div className={styles.content}>
                {/* 왼쪽: 이미지 갤러리 */}
                <ImageGallery
                    imageSrc={menu.imageSrc}
                    altText={menu.korName}
                />

                {/* 오른쪽: 기본 정보 */}
                <div className={styles.rightSection}>
                    <BasicInfo
                        korName={menu.korName}
                        engName={menu.engName}
                        description={menu.description}
                        price={menu.price}
                        categoryName={menu.categoryName}
                        isAvailable={menu.isAvailable}
                        isSoldOut={menu.isSoldOut}
                    />

                    {/* 액션 버튼 */}
                    <MenuActions menuId={menu.id} onDelete={handleDelete} />
                </div>
            </div>
        </main>
    );
}
